import{_ as l,K as i,a as o,c as n,ac as c,q as a,b as r,k as p}from"./chunks/framework.BSuaGltH.js";const C=JSON.parse('{"title":"WebRTC信令、连接与排错 · WebRTC","description":"SDP/ICE、STUN/TURN、协商状态、通道和媒体安全、呼叫状态及多人拓扑。","frontmatter":{"title":"WebRTC信令、连接与排错 · WebRTC","description":"SDP/ICE、STUN/TURN、协商状态、通道和媒体安全、呼叫状态及多人拓扑。","splitFrom":"principles/protocols/webrtc/connection-and-signaling.md","showdocs":{"topics":[{"id":"webrtc","title":"实时通信与 WebRTC","link":"/topics/webrtc/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"信令与传输机制","scope":"general","audience":"general","group":"原理与设计","seriesTitle":"WebRTC信令、连接与排错","summary":"SDP/ICE、STUN/TURN、协商状态、通道和媒体安全、呼叫状态及多人拓扑。","status":"active","related":[{"title":"Coturn 搭建","link":"/principles/protocols/webrtc/coturn-%E6%90%AD%E5%BB%BA","kind":"协商与数据应用","scope":"general","audience":"general"},{"title":"WebRTC信令、连接与排错","link":"/principles/protocols/webrtc/connection-and-signaling","kind":"信令与传输机制","scope":"general","audience":"general"},{"title":"WebRTC信令、连接与排错 · 信令、SDP与ICE连接建立至ICE排错、多人拓扑与带宽","link":"/principles/protocols/webrtc/connection-and-signaling-part-01","kind":"信令与传输机制","scope":"general","audience":"general"},{"title":"手工信令与DataChannel实践","link":"/principles/protocols/webrtc/application","kind":"协商与数据应用","scope":"general","audience":"general"},{"title":"网络：离线推演 DNS 与双向路径证据","link":"/systems/network-remote/network/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"}],"prev":{"text":"WebRTC信令、连接与排错 · 信令、SDP与ICE连接建立至ICE排错、多人拓扑与带宽","link":"/principles/protocols/webrtc/connection-and-signaling-part-01"},"next":{"text":"手工信令与DataChannel实践","link":"/principles/protocols/webrtc/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"WebRTC信令、连接与排错 · 信令、SDP与ICE连接建立至ICE排错、多人拓扑与带宽","link":"/principles/protocols/webrtc/connection-and-signaling-part-01"},"next":{"text":"手工信令与DataChannel实践","link":"/principles/protocols/webrtc/application"}},"headers":[],"relativePath":"principles/protocols/webrtc/connection-and-signaling-part-02.md","filePath":"principles/protocols/webrtc/connection-and-signaling-part-02.md"}'),s={name:"principles/protocols/webrtc/connection-and-signaling-part-02.md"};function b(h,e,g,u,d,f){const t=i("Mermaid");return o(),n("div",null,[e[0]||(e[0]=c('<h1 id="webrtc信令、连接与排错-·-webrtc" tabindex="-1">WebRTC信令、连接与排错 · WebRTC <a class="header-anchor" href="#webrtc信令、连接与排错-·-webrtc" aria-label="Permalink to &quot;WebRTC信令、连接与排错 · WebRTC&quot;">​</a></h1><p><a href="/principles/protocols/webrtc/connection-and-signaling">返回分篇目录</a></p><h2 id="part-4" tabindex="-1">WebRTC <a class="header-anchor" href="#part-4" aria-label="Permalink to &quot;WebRTC {#part-4}&quot;">​</a></h2><h3 id="part-4-webrtc-1" tabindex="-1">WebRTC <a class="header-anchor" href="#part-4-webrtc-1" aria-label="Permalink to &quot;WebRTC {#part-4-webrtc-1}&quot;">​</a></h3><blockquote><p>WebRTC 实时通讯传输音频的场景<br> WebRTC优先使用UDP传输；ICE还需考虑TCP和TURN中继等受限网络路径，不能把RTCPeerConnection等同于单一UDP通道。</p></blockquote><h4 id="part-4-实现目标以及计划" tabindex="-1">实现目标以及计划 <a class="header-anchor" href="#part-4-实现目标以及计划" aria-label="Permalink to &quot;实现目标以及计划 {#part-4-实现目标以及计划}&quot;">​</a></h4><ul><li>音视频即时通讯目标<br><strong>跨平台</strong>、 <strong>高质量</strong>、<strong>高清晰度</strong>，<strong>高流畅度</strong></li><li>第一阶段计划<br> 实现一对一音视频通讯，不考虑清晰度、流畅度、不跨平台</li><li>第二阶段计划<br> 实现多人音视频通讯，不考虑清晰度、流畅度、不跨平台</li><li>第三阶段计划<br> 优化跨平台、流畅度、清晰度</li></ul><h4 id="part-4-需要准备" tabindex="-1">需要准备 <a class="header-anchor" href="#part-4-需要准备" aria-label="Permalink to &quot;需要准备 {#part-4-需要准备}&quot;">​</a></h4><ul><li>WebRTC与WebSocket 技术基础支撑</li><li>反向代理服务(Nginx..)；浏览器采集媒体需要安全上下文，生产通常使用HTTPS，本机可信来源有例外。</li><li>信令服务</li><li>STUN地址发现、TURN中继服务，以及客户端的ICE候选收集和连通检查；ICE不是另一种待部署的穿透服务器。</li></ul><h4 id="part-4-实现思路-个人" tabindex="-1">实现思路（个人） <a class="header-anchor" href="#part-4-实现思路-个人" aria-label="Permalink to &quot;实现思路（个人） {#part-4-实现思路-个人}&quot;">​</a></h4><ul><li>实现唤起界面 <ol><li>A--&gt;B 发起请求音视频通讯通过websocket 推送消息</li><li>至B 同意之后，A、B双方唤起音视频界面</li><li>双方建立RTC（音视频）通讯</li></ol></li><li>信令服务P2P结合WebRTC通讯</li><li>NAT穿透服务（STUN、TURN、ICE）</li><li>多人通讯</li></ul><h5 id="part-4-技术难点" tabindex="-1">技术难点 <a class="header-anchor" href="#part-4-技术难点" aria-label="Permalink to &quot;技术难点 {#part-4-技术难点}&quot;">​</a></h5><ul><li>P2P内网穿透 <ul><li><a href="https://blog.csdn.net/xiongyouqiang/article/details/79185814" target="_blank" rel="noopener noreferrer">ICE介绍</a></li><li><a href="https://github.com/ccding/go-stun" target="_blank" rel="noopener noreferrer">STUN-golang-github</a></li><li><a href="https://blog.csdn.net/dj0379/article/details/52884980" target="_blank" rel="noopener noreferrer">DTLS</a></li><li><a href="https://sourceforge.net/software/voip/" target="_blank" rel="noopener noreferrer">VOIP</a></li><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/API/RTCDataChannel" target="_blank" rel="noopener noreferrer">DataChannel</a></li><li><a href="https://blog.csdn.net/wuxing26jiayou/article/details/79743683" target="_blank" rel="noopener noreferrer">SCTP</a></li><li><a href="https://github.com/coturn/coturn" target="_blank" rel="noopener noreferrer">turn-C/C++-github</a></li></ul></li><li><strong>QoS/QoE</strong>（高质量、高流畅度） <ul><li>QoS需要结合网络设备和系统策略，应用拥塞控制本身不能保证独占带宽。</li><li>其他下载占用带宽时，评估码率自适应、丢包恢复和延迟；没有网络侧策略不能承诺IMClient(APP/PC)始终带宽优先。</li></ul></li><li>丢包 <ul><li>在实现音视频通讯情况下</li><li>丢包以及重新补包</li></ul></li></ul><h4 id="part-4-参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#part-4-参考文章" aria-label="Permalink to &quot;参考文章 {#part-4-参考文章}&quot;">​</a></h4><ul><li><a href="https://github.com/pion/turn" target="_blank" rel="noopener noreferrer">GO-turn</a></li><li><a href="https://www.w3.org/TR/webrtc/#intro" target="_blank" rel="noopener noreferrer">W3c</a></li><li><a href="https://github.com/mehrvarz/rtcchat" target="_blank" rel="noopener noreferrer">go-github-test</a></li><li><a href="https://gortc.io/" target="_blank" rel="noopener noreferrer">go-paclage</a></li><li><a href="https://github.com/pion/webrtc" target="_blank" rel="noopener noreferrer">go-github-pion-package</a></li><li><a href="https://github.com/keroserene/go-webrtc" target="_blank" rel="noopener noreferrer">go+CGO+C/C++-github</a></li><li><a href="https://studygolang.com/articles/14805?fr=sidebar" target="_blank" rel="noopener noreferrer">go-use-rtc</a></li><li><a href="https://www.cnblogs.com/qcjd/p/9324876.html" target="_blank" rel="noopener noreferrer">搭建测试-test</a></li><li><a href="http://www.52im.net/thread-1201-1-1.html" target="_blank" rel="noopener noreferrer">微信实时视频聊天技术的演进</a></li><li><a href="https://www.cnblogs.com/havents/p/10717199.html" target="_blank" rel="noopener noreferrer">必备基础</a></li><li><a href="https://rtcdeveloper.com/t/topic/13341" target="_blank" rel="noopener noreferrer">WebRT 入门</a></li><li><a href="https://yunxin.163.com/blog/52im-18/" target="_blank" rel="noopener noreferrer">网易云信</a></li><li><a href="https://webrtc.org.cn/srtp/" target="_blank" rel="noopener noreferrer">WebRTC client</a></li><li><a href="https://blog.csdn.net/jieqiang3/article/details/89604025" target="_blank" rel="noopener noreferrer">学习网址</a></li><li><a href="https://www.exfo.com/zh/solutions/communication-service-providers/wireless/web-rtc/" target="_blank" rel="noopener noreferrer">..</a></li></ul><h5 id="part-4-stun、turn、ice" tabindex="-1">STUN、TURN、ICE <a class="header-anchor" href="#part-4-stun、turn、ice" aria-label="Permalink to &quot;STUN、TURN、ICE {#part-4-stun、turn、ice}&quot;">​</a></h5><blockquote><p>以下锥形/对称分类是历史简化模型；实际连通性还取决于映射、过滤行为与防火墙，不能仅按一个NAT标签保证UDP穿透成功。</p></blockquote><ul><li>Full Cone NAT： 完全锥形NAT，所有从同一个内网IP和端口号发送过来的请求都会被映射成同一个外网IP和端口号，并且任何一个外网主机都可以通过这个映射的外网IP和端口号向这台内网主机发送包。</li><li>Restricted Cone NAT： 限制锥形NAT，它也是所有从同一个内网IP和端口号发送过来的请求都会被映射成同一个外网IP和端口号。与完全锥形不同的是，外网主机只能够向先前已经向它发送过数据包的内网主机发送包。</li><li>Port Restricted Cone NAT： 端口限制锥形NAT，与限制锥形NAT很相似，只不过它包括端口号。也就是说，一台IP地址X和端口P的外网主机想给内网主机发送包，必须是这台内网主机先前已经给这个IP地址X和端口P发送过数据包。</li><li>Symmetric NAT： 对称NAT，所有从同一个内网IP和端口号发送到一个特定的目的IP和端口号的请求，都会被映射到同一个IP和端口号。如果同一台主机使用相同的源地址和端口号发送包，但是发往不同的目的地，NAT将会使用不同的映射。此外，只有收到数据的外网主机才可以反过来向内网主机发送包</li></ul><h6 id="part-4-进步了解" tabindex="-1">进步了解 <a class="header-anchor" href="#part-4-进步了解" aria-label="Permalink to &quot;进步了解 {#part-4-进步了解}&quot;">​</a></h6><ul><li>STUN（Session Traversal Utilities for NAT）帮助客户端获得服务器看到的映射地址，也用于ICE连通检查；它本身不是完整的NAT穿透方案，不保证识别NAT类型或建立直连。原记录引用的RFC5389已由<a href="https://www.rfc-editor.org/rfc/rfc8489.html" target="_blank" rel="noopener noreferrer">RFC8489</a>取代，受限网络还可能需要TURN中继。</li><li>TURN <ul><li><a href="https://blog.csdn.net/qq_32435729/article/details/78729093" target="_blank" rel="noopener noreferrer">搭建 TURN服务器</a></li><li><a href="https://webrtc.github.io/samples/src/content/peerconnection/trickle-ice/" target="_blank" rel="noopener noreferrer">测试地址</a></li></ul></li><li>ICE</li></ul><details class="details custom-block"><summary>补充实践：WebRTC</summary><blockquote><p>来源：jekyall_blog；原记录日期：未标注。以下保留来源案例的环境和版本范围。</p></blockquote><h3 id="part-4-webrtc-2" tabindex="-1">WebRTC <a class="header-anchor" href="#part-4-webrtc-2" aria-label="Permalink to &quot;WebRTC {#part-4-webrtc-2}&quot;">​</a></h3><h4 id="part-4-概述" tabindex="-1">概述 <a class="header-anchor" href="#part-4-概述" aria-label="Permalink to &quot;概述 {#part-4-概述}&quot;">​</a></h4><ul><li>官网:<a href="https://webrtc.org/" target="_blank" rel="noopener noreferrer">https://webrtc.org/</a><ul><li><a href="https://webrtc.github.io/samples/" target="_blank" rel="noopener noreferrer">https://webrtc.github.io/samples/</a></li><li>APIs介绍:<a href="https://webrtc.org/" target="_blank" rel="noopener noreferrer">https://webrtc.org/</a></li></ul></li><li>WebRTC 协议介绍</li></ul><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/API/WebRTC_API/Protocols" target="_blank" rel="noopener noreferrer">https://developer.mozilla.org/zh-CN/docs/Web/API/WebRTC_API/Protocols</a></p></blockquote></details><h3 id="part-4-将呼叫邀请与连接协商分开" tabindex="-1">将呼叫邀请与连接协商分开 <a class="header-anchor" href="#part-4-将呼叫邀请与连接协商分开" aria-label="Permalink to &quot;将呼叫邀请与连接协商分开 {#part-4-将呼叫邀请与连接协商分开}&quot;">​</a></h3><p>旧计划中的“B同意”属于产品呼叫状态，随后仍要完成会话描述交换、候选检查和安全传输建立。拒绝邀请、用户撤销、连接失败与通话结束应是不同状态；重复或延迟到达的信令应关联呼叫ID，避免结束后的旧消息重新唤起界面。图示是对历史计划的机制整理，未建立真实音视频连接。</p>',23)),a(t,{source:""}),e[1]||(e[1]=r("h3",{id:"part-4-多人方案的路径差异",tabindex:"-1"},[p("多人方案的路径差异 "),r("a",{class:"header-anchor",href:"#part-4-多人方案的路径差异","aria-label":'Permalink to "多人方案的路径差异 {#part-4-多人方案的路径差异}"'},"​")],-1)),e[2]||(e[2]=r("p",null,"全网状适合说明端点直接交互，但每增加一人都会增加多条连接和上传副本。SFU集中接收并按订阅转发，MCU还会进行混合处理；二者都需要服务端容量和故障设计。TURN只是中继某条传输路径，不能因为所有流量经过同一TURN主机就把它称作SFU或MCU。",-1)),a(t,{source:"Zmxvd2NoYXJ0IExSCkFbIuWPguS4juiAhSBBIl0gPC0tPnwi5aqS5L2TInwgU1siU0ZV77ya5oyJ6K6i6ZiF6L2s5Y+RIl0KQlsi5Y+C5LiO6ICFIEIiXSA8LS0+fCLlqpLkvZMifCBTCkNbIuWPguS4juiAhSBDIl0gPC0tPnwi5aqS5L2TInwgUwpTIC0tPiBOWyLmnI3liqHlmajmib/mi4Xovazlj5HluKblrr3kuI7osIPluqYiXQo="})])}const T=l(s,[["render",b]]);export{C as __pageData,T as default};
